/// Lossless enum: values Stripe documents plus any value the API
/// adds later, kept in `undocumented` instead of dropped.
public enum ApiErrorsType: Sendable, Equatable, Hashable, LosslessEnum {
    case apiError
    case cardError
    case idempotencyError
    case invalidRequestError
    case undocumented(String)

    public init(rawValue raw: String) {
        switch raw {
        case "api_error": self = .apiError
        case "card_error": self = .cardError
        case "idempotency_error": self = .idempotencyError
        case "invalid_request_error": self = .invalidRequestError
        default: self = .undocumented(raw)
        }
    }

    public var rawValue: String {
        switch self {
        case .apiError: return "api_error"
        case .cardError: return "card_error"
        case .idempotencyError: return "idempotency_error"
        case .invalidRequestError: return "invalid_request_error"
        case .undocumented(let value): return value
        }
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        self.init(rawValue: try container.decode(String.self))
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.singleValueContainer()
        try container.encode(rawValue)
    }
}

